def build_agent(sandbox):
    n_blocks = 6  # Use more blocks to improve stability
    positions = [0.12]  # Start with the top block at x = 0.12

    # Compute positions in harmonic stack
    for i in range(1, n_blocks):
        current_com = sum(positions) / len(positions)
        new_x = current_com - 0.5  # Place new block so that its right edge is at the current COM
        positions.insert(0, new_x)

    # Stack blocks vertically with increasing density from top to bottom
    for i, x in enumerate(positions):
        y = 0.1 + i * 0.2  # Vertical stacking at y = 0.1, 0.3, 0.5, ...
        # Assign higher density to lower blocks to increase stability
        if i < 2:
            density = 10.0  # Bottom 2 blocks with high density
        elif i < 4:
            density = 5.0  # Next 2 blocks
        else:
            density = 1.0  # Top 2 blocks
        sandbox.add_block(x, y, 1.0, 0.2, density=density)

    return None


